// Hand-written wire types for the HTTP API (apps/api). IPC types are generated
// from Rust into ./generated by `pnpm gen:protocol` and must not be edited.

export type Health = {
  ok: true;
  version: string;
};

/** RFC 9457 Problem Details. `code` is a stable machine code. */
export type Problem = {
  type: string;
  title: string;
  status: number;
  detail?: string;
  code?: string;
  instance?: string;
};
